    rgba(0, 0, 0, 0.25) 0px 12px 12px -6px,
    rgba(0, 0, 0, 0.25) 0px 24px 24px -12px,
    rgba(0, 0, 0, 0.25) 0px 48px 48px -24px;
  --elevation-2xl:
    rgba(0, 0, 0, 0.35) 0px 0px 0px 1px,
    rgba(0, 0, 0, 0.3) 0px 3px 3px -1.5px,
